import { useCallback, useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { subscribeToToasts } from '../lib/toastBus'

const TOAST_VISIBLE_MS = 12000
const EXIT_ANIMATION_MS = 350

function Toast({ id, title, onOpen, onDismiss, persistent = false }) {
  const [exiting, setExiting] = useState(false)

  useEffect(() => {
    if (persistent) return
    const exitTimer = setTimeout(() => setExiting(true), TOAST_VISIBLE_MS - EXIT_ANIMATION_MS)
    const removeTimer = setTimeout(() => onDismiss(id), TOAST_VISIBLE_MS)
    return () => {
      clearTimeout(exitTimer)
      clearTimeout(removeTimer)
    }
  }, [id, onDismiss, persistent])

  const handleClick = () => {
    onOpen?.()
    onDismiss(id)
  }

  return (
    <div
      onClick={handleClick}
      className={`
        liquid-glass-toast
        relative
        px-6 py-3.5 rounded-[22px]
        max-w-md w-full
        pointer-events-auto cursor-pointer
        ${exiting ? 'animate-toast-out' : 'animate-toast-in'}
      `}
    >
      <p
        className="font-display text-[17px] font-semibold text-black truncate"
        style={{ letterSpacing: '-0.015em' }}
      >
        {title}
      </p>
    </div>
  )
}

export default function ToastContainer() {
  const [toasts, setToasts] = useState([])

  useEffect(() => subscribeToToasts((toast) => {
    setToasts(previousToasts => {
      const nextToast = { ...toast, id: `${Date.now()}-${Math.random().toString(16).slice(2)}` }
      return [...previousToasts, nextToast].slice(-2)
    })
  }), [])

  const dismiss = useCallback((id) => setToasts(prev => prev.filter(t => t.id !== id)), [])

  return createPortal(
    <>
      <LiquidGlassFilter />
      <div className="fixed top-4 left-0 right-0 z-[300] flex flex-col items-center gap-2.5 pointer-events-none px-4">
        <Toast id="mock" title="AI models now reason better than most humans on complex tasks" onDismiss={() => {}} persistent />
        {toasts.map(toast => (
          <Toast key={toast.id} {...toast} onDismiss={dismiss} />
        ))}
      </div>
    </>,
    document.body
  )
}

/* Refraction via self-referential displacement: the backdrop displaces itself.
 * R channel drives X displacement, B channel drives Y. Content edges (where
 * R/B change steeply, e.g. dark text on white) generate the strongest
 * displacement gradients, so text underneath the toast gets visibly warped
 * across the entire element body — not just at the perimeter. This is the
 * apple-liquid-glass-experiments technique.
 *
 * Chrome/Firefox only; Safari silently no-ops `backdrop-filter: url()`,
 * falling through to the box-shadow specular stack. */
function LiquidGlassFilter() {
  return (
    <svg width="0" height="0" aria-hidden="true" style={{ position: 'absolute' }}>
      <filter id="liquid-glass-lens" x="-10%" y="-10%" width="120%" height="120%" color-interpolation-filters="linearRGB">
        <feDisplacementMap in="SourceGraphic" in2="SourceGraphic" scale="40" xChannelSelector="R" yChannelSelector="B" />
      </filter>
    </svg>
  )
}

@import "tailwindcss";
@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&display=swap');
@plugin "@tailwindcss/typography";

@theme {
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: "Lora", serif;

  --color-brand-50: #f0f9ff;
  --color-brand-100: #e0f2fe;
  --color-brand-200: #bae6fd;
  --color-brand-300: #7dd3fc;
  --color-brand-400: #38bdf8;
  --color-brand-500: #0ea5e9;
  --color-brand-600: #0284c7;
  --color-brand-700: #0369a1;
  --color-brand-800: #075985;
  --color-brand-900: #0c4a6e;

  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-elevated: 0 4px 16px rgba(0, 0, 0, 0.08), 0 1px 4px rgba(0, 0, 0, 0.04);

  --ease-springy: cubic-bezier(0.16, 1, 0.3, 1);
}

@layer base {
  body {
    @apply bg-slate-50 text-slate-900 antialiased;
  }
}

.prose h1,
.prose-sm h1 {
  margin-top: 1.2em;
  margin-bottom: 0.5em;
}

.prose h2 {
  margin-top: 1.4em;
  margin-bottom: 0.4em;
}

/* 0-indent list overrides */
.prose ul,
.prose ol {
  padding-left: 1.2em; /* Aligns bullet with regular text (p) start */
}

.prose li {
  padding-left: 0;
  margin-left: 0;
}

@keyframes zen-enter {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@utility animate-zen-enter {
  animation: zen-enter 300ms var(--ease-springy) forwards;
}

@keyframes check-enter {
  from {
    transform: scale(0);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

@utility animate-check-enter {
  animation: check-enter 150ms var(--ease-springy) forwards;
}

@keyframes dock-action-enter {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@utility animate-dock-action-enter {
  animation: dock-action-enter 220ms var(--ease-springy) both;
}

@keyframes overlay-menu-enter {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@utility animate-overlay-menu-enter {
  animation: overlay-menu-enter 130ms var(--ease-springy) both;
}

/* ── Article card border glow — summary loading state ──
 *
 * One ::after pseudo-element on [data-summary-status] drives the border animation.
 * A spark orbits the card border while a summary is loading; fades when done.
 *
 * --border-angle is GPU-composited via @property to allow conic-gradient animation.
 */

@property --border-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

[data-summary-status]::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  pointer-events: none;
  z-index: 20;
  opacity: 0;
  background:
    conic-gradient(
      from var(--border-angle),
      transparent 0%,
      hsl(210 95% 76%) 2%,
      hsl(210 90% 82%) 4.5%,
      hsl(210 70% 88% / 0.3) 9.5%,
      transparent 12%,
      transparent 100%
    ),
    conic-gradient(from 0deg, hsl(210 70% 82% / 0.1) 0 100%);
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  transition: opacity 300ms ease;
}

[data-summary-status="loading"]::after {
  opacity: 1;
}

@keyframes spark-orbit {
  to { --border-angle: 360deg; }
}

/* Digital distortion on card content: once every two spark cycles (5s), the text briefly
 * RGB-splits and jitters — snappy steps simulate signal interference, ease-out recovery
 * simulates the energy wave passing through. Total visible window: ~600ms. */
@keyframes text-distort {
  0% {
    transform: translate(0, 0);
    filter: brightness(1) drop-shadow(0 0 0 transparent) drop-shadow(0 0 0 transparent);
    animation-timing-function: steps(1, end);
  }
  2.4% {
    transform: translate(-1.5px, 0);
    filter: brightness(1.04) drop-shadow(-2px 0 0 hsl(0 85% 55% / 0.22)) drop-shadow(2px 0 0 hsl(210 90% 60% / 0.22));
    animation-timing-function: steps(1, end);
  }
  4.8% {
    transform: translate(1.5px, 0);
    filter: brightness(1.06) drop-shadow(-2px 0 0 hsl(0 85% 55% / 0.19)) drop-shadow(2px 0 0 hsl(210 90% 60% / 0.19));
    animation-timing-function: steps(1, end);
  }
  7.6% {
    transform: translate(-0.8px, 0);
    filter: brightness(1.02) drop-shadow(-1px 0 0 hsl(0 85% 55% / 0.08)) drop-shadow(1px 0 0 hsl(210 90% 60% / 0.08));
    animation-timing-function: ease-out;
  }
  12%, 100% {
    transform: translate(0, 0);
    filter: brightness(1) drop-shadow(0 0 0 transparent) drop-shadow(0 0 0 transparent);
  }
}

@media (prefers-reduced-motion: no-preference) {
  [data-summary-status="loading"]::after {
    animation: spark-orbit 2.5s linear infinite;
  }

  [data-summary-status="loading"] > div {
    animation: text-distort 5s linear infinite;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-summary-status="loading"]::after {
    background:
      conic-gradient(
        from 45deg,
        transparent 0%,
        hsl(210 95% 76%) 3%,
        hsl(210 90% 82%) 7%,
        hsl(210 70% 88% / 0.25) 14%,
        transparent 16%,
        transparent 100%
      ),
      conic-gradient(from 0deg, hsl(210 70% 82% / 0.12) 0 100%);
  }
}

@keyframes toast-slide-in {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes toast-slide-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(-10px) scale(0.97);
  }
}

@utility animate-toast-in {
  animation: toast-slide-in 520ms cubic-bezier(0.33, 1, 0.68, 1) forwards;
}

@utility animate-toast-out {
  animation: toast-slide-out 350ms cubic-bezier(0.32, 0, 0.67, 0) forwards;
}

/* ── Liquid Glass — Toast (solid variant) ──
 *
 * The "solid" Liquid Glass for use over neutral/light backgrounds where the
 * translucent variant has nothing colorful to refract. Near-opaque cream-white
 * surface that still preserves the rim, top specular ridge, and soft drop
 * shadow. A small amount of backdrop blur lets the surface pick up a hint of
 * the background's tint so the pill never looks "pasted on."
 *
 * Light catches the upper rim (bright inset) and the lower rim sits in shadow
 * (dark inset) — together they sell the curved-glass illusion without any
 * transparency. A hairline outer ring defines the silhouette.
 */
.liquid-glass-toast {
  --lg-light: #ffffff;
  --lg-dark: #001428;

  position: relative;
  /* Vertical gradient sells convex curvature (top catches light, bottom sits
   * in self-shadow). Opacity ramps 88% → 72% — solid enough that the toast
   * is a substantial surface, translucent enough to feel like real glass.
   *
   * brightness(1.1) is the key dampening ingredient: it lifts dark content
   * beneath the toast toward middle-gray, reducing its contrast (and thus
   * its attention pull) without destroying shapes. Lighter literal blur lets
   * the rim refraction read clearly. */
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--lg-light) 88%, transparent) 0%,
      color-mix(in srgb, var(--lg-light) 80%, transparent) 55%,
      color-mix(in srgb, var(--lg-light) 72%, transparent) 100%
    );
  backdrop-filter: blur(12px) saturate(135%) brightness(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(135%) brightness(1.1);
  box-shadow:
    /* Hairline perimeter — defines the silhouette */
    inset 0 0 0 0.5px color-mix(in srgb, var(--lg-dark) 13%, transparent),
    /* Crisp 1.5px bright top rim — the strongest specular cue, pushed harder */
    inset 0 1.5px 0 -0.25px color-mix(in srgb, var(--lg-light) 100%, transparent),
    /* Broad soft top glow — light-from-above band, deepened */
    inset 0 14px 16px -10px color-mix(in srgb, var(--lg-light) 100%, transparent),
    /* Faint dark bottom rim — the curved underside sitting in shadow, pushed harder */
    inset 0 -1.25px 0 -0.5px color-mix(in srgb, var(--lg-dark) 15%, transparent),
    /* Soft inner shadow at the bottom — deeper convex feel */
    inset 0 -10px 14px -8px color-mix(in srgb, var(--lg-dark) 13%, transparent),
    /* Elevation */
    0 1px 2px 0 color-mix(in srgb, var(--lg-dark) 9%, transparent),
    0 14px 36px -4px color-mix(in srgb, var(--lg-dark) 16%, transparent);
}

/* Progressive enhancement: in browsers that support SVG filters in
 * backdrop-filter (Chrome/Firefox), chain the radial displacement map so
 * content underneath the toast bends at the rim — the "light distortion at
 * the border" that the slider-button reference demonstrates. Safari silently
 * no-ops the url() and falls through to the rule above. */
@supports (backdrop-filter: url(#liquid-glass-lens)) or (-webkit-backdrop-filter: url(#liquid-glass-lens)) {
  .liquid-glass-toast {
    backdrop-filter: blur(4px) saturate(140%) brightness(1.1) url(#liquid-glass-lens);
    -webkit-backdrop-filter: blur(4px) saturate(140%) brightness(1.1) url(#liquid-glass-lens);
  }
}

const subscribers = new Set()

export function emitToast(toast) {
  for (const callback of subscribers) {
    callback(toast)
  }
}

export function subscribeToToasts(callback) {
  subscribers.add(callback)
  return () => subscribers.delete(callback)
}

